package cloud.gitwide.ampverse;

import android.content.Context;
import androidx.media3.common.MediaItem;
import java.util.*;
import org.json.*;

/** Desktop-compatible eligibility over synced preparation. Never runs analysis. */
final class PhoneSmartRules {
    static final String[] FIELDS={"Bpm","TempoAlternative","Key","Camelot","Energy","Duration","TempoConfidence","KeyConfidence","Analyzed","Reviewed","BeatGrid","ManualEdits","CueCount","ManualCueCount","CueKind","CueLabel","SectionCount","SectionName","SectionEnergy","EnergyProfile","Engine","BeatOffset","CueIn","CueOut","StemCount","Artist","Album","Year","Rating","Bitrate","SampleRate","Channels"};
    static final String[] LABELS={"BPM","Alternative BPM","Musical key","Camelot key","Energy (1–10)","Duration (seconds)","BPM confidence (%)","Key confidence (%)","Has analysis","Analysis reviewed","Has beatgrid","Has manual edits","Cue count","Manual cue count","Cue type","Cue label","Section count","Section label","Any section energy (1–10)","Has energy profile","Analysis engine","Beat offset (seconds)","Cue-in (seconds)","Cue-out (seconds)","Recorded stem count","Artist","Album","Year tag","Rating","Bitrate (kbps)","Sample rate (Hz)","Audio channels"};
    static String kind(String f){return Arrays.asList("Key","Camelot","CueKind","CueLabel","SectionName","Engine","Artist","Album","Year").contains(f)?"Text":Arrays.asList("Analyzed","Reviewed","BeatGrid","ManualEdits","EnergyProfile").contains(f)?"Flag":"Number";}
    static double max(String f){switch(f){case "Bpm":case "TempoAlternative":return 400;case "Energy":case "SectionEnergy":return 10;case "TempoConfidence":case "KeyConfidence":return 100;case "Rating":return 5;case "CueCount":case "ManualCueCount":return 256;case "SectionCount":return 4096;case "StemCount":case "Channels":return 32;case "Bitrate":return 10000;case "SampleRate":return 384000;default:return 21600;}}
    static double min(String f){return f.equals("Energy")||f.equals("SectionEnergy")?1:0;}
    static JSONObject object(JSONObject p,String k){JSONObject v=p.optJSONObject(k);return v==null?new JSONObject():v;}
    static JSONArray array(JSONObject p,String k){JSONArray a=p.optJSONArray(k);return a==null?new JSONArray():a;}
    static void strings(Object value,List<String> out){if(value instanceof JSONArray){JSONArray a=(JSONArray)value;for(int i=0;i<a.length();i++)strings(a.opt(i),out);}else if(value!=null&&value!=JSONObject.NULL)out.add(value.toString());}
    static String genre(String s){s=s.trim().toLowerCase(Locale.ROOT);return Arrays.asList("rnb","r & b","rhythm and blues","rhythm & blues").contains(s)?"r&b":s;}
    static List<String> genres(MediaItem item){JSONObject x=object(DjEngine.preparation(item),"extensions");List<String> raw=new ArrayList<>(),out=new ArrayList<>();strings(x.has("genre")?x.opt("genre"):x.opt("embedded_genres"),raw);for(String s:raw)for(String g:s.split("[;/\\x00]"))if(!g.trim().isEmpty())out.add(genre(g));return out;}
    static List<String> text(Context c,MediaItem item,String f){JSONObject p=DjEngine.preparation(item),x=object(p,"extensions"),a=object(p,"analysis");List<String> out=new ArrayList<>();switch(f){case "Key":case "Camelot":String k=f.equals("Key")?"key":"harmonic_key";String saved=c.getSharedPreferences("phone-track-details",0).getString(item.mediaId+":key","");strings(!saved.isEmpty()&&f.equals("Camelot")?saved:p.opt(k),out);break;case "Engine":strings(a.opt("engine"),out);break;case "Artist":case "Album":case "Year":String key=f.toLowerCase(Locale.ROOT);strings(x.has(key)?x.opt(key):object(x,"embedded_tags").opt(f.equals("Artist")?"TrackArtist":f.equals("Album")?"AlbumTitle":"RecordingDate"),out);if(out.isEmpty()&&f.equals("Artist"))strings(item.mediaMetadata.artist,out);if(out.isEmpty()&&f.equals("Album"))strings(item.mediaMetadata.albumTitle,out);break;case "CueKind":case "CueLabel":for(String collection:new String[]{"cues","manual_cues"}){JSONArray cues=array(p,collection);for(int i=0;i<cues.length();i++)strings(cues.optJSONObject(i)==null?null:cues.optJSONObject(i).opt(f.equals("CueKind")?"kind":"label"),out);}break;case "SectionName":JSONArray sections=array(object(x,"energy_profile"),"sections");for(int i=0;i<sections.length();i++)strings(sections.optJSONObject(i)==null?null:sections.optJSONObject(i).opt("name"),out);break;}return out;}
    static double number(Context c,MediaItem item,String f){JSONObject p=DjEngine.preparation(item),x=object(p,"extensions"),a=object(p,"analysis"),props=object(x,"audio_properties");switch(f){case "Bpm":double bpm=PhonePlaylists.bpm(c,item);return bpm>0?bpm:Double.NaN;case "Energy":double e=PhonePlaylists.knownEnergy(c,item);return Double.isFinite(e)?1+9*e:Double.NaN;case "Duration":return a.optDouble("duration",props.optDouble("duration",p.optDouble("cue_out",Double.NaN)));case "TempoConfidence":return a.optDouble("tempo_confidence",Double.NaN)*100;case "KeyConfidence":return a.optDouble("key_confidence",Double.NaN)*100;case "CueCount":return array(p,"cues").length()+array(p,"manual_cues").length();case "ManualCueCount":return array(p,"manual_cues").length();case "SectionCount":return x.has("energy_profile")?array(object(x,"energy_profile"),"sections").length():Double.NaN;case "StemCount":return array(p,"stems").length();case "BeatOffset":return p.optDouble("beat_offset",Double.NaN);case "CueIn":return p.optDouble("cue_in",0);case "CueOut":return p.optDouble("cue_out",Double.NaN);case "Rating":return c.getSharedPreferences("phone-track-details",0).contains(item.mediaId+":rating")?c.getSharedPreferences("phone-track-details",0).getInt(item.mediaId+":rating",0):x.optDouble("rating",Double.NaN);case "Bitrate":return props.optDouble("bitrate",Double.NaN);case "SampleRate":return props.optDouble("sample_rate",Double.NaN);case "Channels":return props.optDouble("channels",Double.NaN);default:return Double.NaN;}}
    static boolean flag(MediaItem item,String f){JSONObject p=DjEngine.preparation(item);switch(f){case "Analyzed":return p.optJSONObject("analysis")!=null;case "Reviewed":return object(p,"analysis").optBoolean("reviewed");case "BeatGrid":return !p.isNull("bpm")&&p.has("bpm")&&p.has("beat_offset")&&!p.isNull("beat_offset");case "ManualEdits":return p.optBoolean("manual_override")||array(p,"manual_cues").length()>0;case "EnergyProfile":return object(p,"extensions").has("energy_profile");default:return false;}}
    static List<MediaItem> repeatCandidates(List<MediaItem> source,Collection<String> recent,String current,int avoid){List<MediaItem> next=new ArrayList<>();for(MediaItem item:source)if(!item.mediaId.equals(current)&&(avoid==0||!recent.contains(item.mediaId)))next.add(item);if(next.isEmpty())for(MediaItem item:source)if(!item.mediaId.equals(current))next.add(item);return next;}
    static long entry(MediaItem item,JSONObject rules){long fallback=DjEngine.cueIn(item);if(!rules.optString("style","Steady").equalsIgnoreCase("Hype")||!rules.optBoolean("use_manual_cues",true))return fallback;JSONObject p=DjEngine.preparation(item);JSONArray cues=array(p,"manual_cues");double end=p.optDouble("cue_out",Double.POSITIVE_INFINITY);for(int i=0;i<cues.length();i++){JSONObject cue=cues.optJSONObject(i);if(cue==null)continue;String label=cue.optString("label").toLowerCase(Locale.ROOT);double seconds=cue.optDouble("seconds",Double.NaN);if((label.contains("drop")||label.contains("build"))&&Double.isFinite(seconds)&&seconds>=0&&seconds<end)return (long)(seconds*1000);}return fallback;}
    static boolean contains(JSONArray a,String id){if(a!=null)for(int i=0;i<a.length();i++)if(id.equals(a.optString(i)))return true;return false;}
    static boolean matches(Context c,MediaItem item,JSONObject list){if(contains(list.optJSONArray("excluded"),item.mediaId))return false;JSONArray chosen=list.optJSONArray("genres");if(chosen!=null&&chosen.length()>0){List<String> tags=genres(item);boolean match=false;for(int i=0;i<chosen.length();i++)match|=tags.contains(genre(chosen.optString(i)));if(!match)return false;}JSONArray filters=array(list,"filters");for(int i=0;i<filters.length();i++){JSONObject filter=filters.optJSONObject(i);if(filter==null)return false;String f=filter.optString("field"),type=filter.optString("type");if(!Arrays.asList(FIELDS).contains(f)||!kind(f).equals(type))return false;if(type.equals("Flag")){if(flag(item,f)!=filter.optBoolean("value"))return false;}else if(type.equals("Text")){List<String> values=text(c,item,f);String[] terms=filter.optString("terms").toLowerCase(Locale.ROOT).split(";");boolean match=false;for(String value:values){String v=value.trim().toLowerCase(Locale.ROOT);if(v.isEmpty())continue;boolean hasTerm=false;for(String term:terms)if(!term.trim().isEmpty()){hasTerm=true;if(filter.optBoolean("exact",true)?v.equals(term.trim()):v.contains(term.trim()))match=true;}if(!hasTerm)match=true;}if(!match)return false;}else{double lo=filter.optDouble("min",Double.NaN),hi=filter.optDouble("max",Double.NaN);if(!Double.isFinite(lo)||!Double.isFinite(hi)||lo>hi||lo<min(f)||hi>max(f))return false;boolean match=false;if(f.equals("TempoAlternative")||f.equals("SectionEnergy")){JSONObject x=object(DjEngine.preparation(item),"extensions");JSONArray values=f.equals("TempoAlternative")?array(x,"tempo_alternatives"):array(object(x,"energy_profile"),"sections");for(int j=0;j<values.length();j++){double n=f.equals("TempoAlternative")?values.optDouble(j,Double.NaN):values.optJSONObject(j)==null?Double.NaN:1+9*values.optJSONObject(j).optDouble("energy",Double.NaN);match|=Double.isFinite(n)&&n>=lo&&n<=hi;}}else{double n=number(c,item,f);match=Double.isFinite(n)&&n>=lo&&n<=hi;}if(!match)return false;}}return true;}
}
